/// Why a walk of a union's list refused it, beside the record's index and byte offset in a
/// `UnionError`.
#[repr(i32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum UnionClause {
    /// header past the extent
    HeaderPastExtent = 1,
    /// unknown tag
    UnknownTag,
    /// size is not the member's
    SizeNotTheMembers,
    /// record past the extent
    RecordPastExtent,
    /// count not met
    CountNotMet,
    /// offset is not a record's start
    NotARecordStart,
}

impl core::fmt::Display for UnionClause {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(match self {
            UnionClause::HeaderPastExtent => "header past the extent",
            UnionClause::UnknownTag => "unknown tag",
            UnionClause::SizeNotTheMembers => "size is not the member's",
            UnionClause::RecordPastExtent => "record past the extent",
            UnionClause::CountNotMet => "count not met",
            UnionClause::NotARecordStart => "offset is not a record's start",
        })
    }
}

/// Where a walk of a sequence refused it: the record's index, its byte offset, the clause.
