/// one note: the struct its head's kind names, head.size bytes long
#[derive(Clone, Copy, Debug)]
pub enum NoteRef<'a> {
    Line(&'a NoteLine),
    /// a value and its flag
    Mark(&'a NoteMark),
}

const _: () =
    assert!(core::mem::size_of::<NoteHead>() == 8 && core::mem::align_of::<NoteHead>() == 4);
const _: () =
    assert!(core::mem::size_of::<NoteLine>() == 16 && core::mem::align_of::<NoteLine>() == 4);
const _: () =
    assert!(core::mem::size_of::<NoteMark>() == 16 && core::mem::align_of::<NoteMark>() == 4);

/// The list's alignment, the unit of `NoteSequence::at`'s index.
pub const NOTE_ALIGN: usize = 4;

/// A list of `note`'s members back to back, each by its own size, as a C caller or the
/// library delivered it: `records()` walks it and `at()` resolves an offset in units of the list's
/// alignment, each refusing a malformed record and reading no byte past the extent.
#[derive(Clone, Copy)]
pub struct NoteSequence<'a> {
    bytes: &'a [u8],
    count: u32,
}

impl<'a> NoteSequence<'a> {
    /// The number of records, as the producer counted them.
    pub fn count(&self) -> u32 {
        self.count
    }

    /// The records' bytes, the extent their length.
    pub fn bytes(&self) -> &'a [u8] {
        self.bytes
    }

    /// The records in order, ending at the first one refused, which is yielded as the error.
    pub fn records(&self) -> NoteRecords<'a> {
        NoteRecords {
            sequence: *self,
            offset: 0,
            index: 0,
            done: false,
        }
    }

    /// The record at byte `index` × `NOTE_ALIGN` from the sequence's start, found by walking from
    /// the start, the byte offset saturating at `u32::MAX`.
    pub fn at(&self, index: u32) -> Result<NoteRef<'a>, UnionError> {
        let offset = index.saturating_mul(NOTE_ALIGN as u32);
        let target = offset as usize;
        let mut records = self.records();
        loop {
            let (walked, here) = (records.index, records.offset);
            match records.next() {
                Some(Ok(record)) if here == target => return Ok(record),
                Some(Ok(_)) if here < target => {}
                Some(Err(error)) => return Err(error),
                _ => {
                    return Err(UnionError {
                        index: walked,
                        offset,
                        clause: UnionClause::NotARecordStart,
                    });
                }
            }
        }
    }

    /// The record at byte `offset`, a record's start the walk reached, and its size: refused where
    /// fewer than the prefix's bytes remain, its tag names no member, its size is not that member's,
    /// or its bytes pass the extent.
    fn record(&self, offset: usize) -> Result<(NoteRef<'a>, usize), UnionClause> {
        let rest = &self.bytes[offset..];
        if rest.len() < 8 {
            return Err(UnionClause::HeaderPastExtent);
        }
        let start = rest.as_ptr();
        // SAFETY: the sequence's start is aligned to the prefix and every size the walk stepped by is
        // a multiple of its alignment; the prefix's bytes remain, and any bytes are a valid prefix.
        let head = unsafe { &*start.cast::<NoteHead>() };
        let size = match head.kind {
            1 => 16,
            2 => 16,
            _ => return Err(UnionClause::UnknownTag),
        };
        if head.size as usize != size {
            return Err(UnionClause::SizeNotTheMembers);
        }
        if rest.len() < size {
            return Err(UnionClause::RecordPastExtent);
        }
        // SAFETY: as for the prefix, whose alignment every member has; the tag names this member,
        // its size remains, and any bytes are a valid member.
        let record = unsafe {
            match head.kind {
                1 => NoteRef::Line(&*start.cast::<NoteLine>()),
                _ => NoteRef::Mark(&*start.cast::<NoteMark>()),
            }
        };
        Ok((record, size))
    }
}

/// The walk of a `NoteSequence`: each record in order, then, where the walk refuses one, its error
/// once.
pub struct NoteRecords<'a> {
    sequence: NoteSequence<'a>,
    offset: usize,
    index: u32,
    done: bool,
}

impl<'a> Iterator for NoteRecords<'a> {
    type Item = Result<NoteRef<'a>, UnionError>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.done {
            return None;
        }
        let left = self.sequence.bytes.len() - self.offset;
        let counted = self.index == self.sequence.count;
        if left == 0 && counted {
            self.done = true;
            return None;
        }
        let walked = if left == 0 || counted {
            Err(UnionClause::CountNotMet)
        } else {
            self.sequence.record(self.offset)
        };
        match walked {
            Ok((record, size)) => {
                self.offset += size;
                self.index += 1;
                Some(Ok(record))
            }
            Err(clause) => {
                self.done = true;
                Some(Err(UnionError {
                    index: self.index,
                    offset: self.offset as u32,
                    clause,
                }))
            }
        }
    }
}

