/// A sequence of `note` being written: `push_line`, `push_mark` set the record's tag and
/// size; the buffer's words are aligned to the prefix; `view()` and `tail(mark)` are the views.
#[derive(Default)]
pub struct NoteBuf {
    words: Vec<u32>,
    count: u32,
}

/// A place in a `NoteBuf`: the word and the count at the time, for `tail`.
#[derive(Clone, Copy)]
pub struct NoteBufMark {
    word: usize,
    count: u32,
}

impl NoteBuf {
    /// An empty buffer.
    pub fn new() -> Self {
        Self::default()
    }

    /// Appends `record` as a `line`, its `kind` and `size` the member's whatever it holds.
    pub fn push_line(&mut self, record: &NoteLine) {
        let mut staged = [0u8; 16];
        staged[0..2].copy_from_slice(&1u16.to_ne_bytes());
        staged[2..4].copy_from_slice(&16u16.to_ne_bytes());
        staged[4..8].copy_from_slice(&record.head.at.to_ne_bytes());
        staged[8..12].copy_from_slice(&record.label.offset.to_ne_bytes());
        staged[12..16].copy_from_slice(&record.label.length.to_ne_bytes());
        self.push(&staged);
    }

    /// Appends `record` as a `mark`, its `kind` and `size` the member's whatever it holds.
    pub fn push_mark(&mut self, record: &NoteMark) {
        let mut staged = [0u8; 16];
        staged[0..2].copy_from_slice(&2u16.to_ne_bytes());
        staged[2..4].copy_from_slice(&16u16.to_ne_bytes());
        staged[4..8].copy_from_slice(&record.head.at.to_ne_bytes());
        staged[8..12].copy_from_slice(&record.value.to_ne_bytes());
        staged[12..16].copy_from_slice(&record.flag.to_ne_bytes());
        self.push(&staged);
    }

    /// The number of records pushed.
    pub fn count(&self) -> u32 {
        self.count
    }

    /// The bytes pushed.
    pub fn bytes_len(&self) -> usize {
        self.words.len() * 4
    }

    /// The bytes the buffer holds before it reallocates.
    pub fn capacity_bytes(&self) -> usize {
        self.words.capacity() * 4
    }

    /// The buffer's end now, for a later `tail`.
    pub fn mark(&self) -> NoteBufMark {
        NoteBufMark {
            word: self.words.len(),
            count: self.count,
        }
    }

    /// Every record pushed.
    pub fn view(&self) -> NoteSequence<'_> {
        self.tail(NoteBufMark { word: 0, count: 0 })
    }

    /// The records pushed since `from`, a mark of this buffer.
    pub fn tail(&self, from: NoteBufMark) -> NoteSequence<'_> {
        let words = &self.words[from.word..];
        // SAFETY: the words are initialised, and bytes have no alignment of their own.
        let bytes = unsafe {
            core::slice::from_raw_parts(words.as_ptr().cast::<u8>(), core::mem::size_of_val(words))
        };
        NoteSequence {
            bytes,
            count: self.count - from.count,
        }
    }

    /// Appends one record's bytes as words and counts it; the whole stays within the bytes a `u32`
    /// extent counts.
    fn push(&mut self, record: &[u8]) {
        assert!(
            u32::try_from(self.bytes_len() + record.len()).is_ok(),
            "a NoteBuf holds at most u32::MAX bytes"
        );
        self.words.reserve(record.len() / 4);
        for at in (0..record.len()).step_by(4) {
            self.words.push(u32::from_ne_bytes([
                record[at],
                record[at + 1],
                record[at + 2],
                record[at + 3],
            ]));
        }
        self.count += 1;
    }
}

/// A C element count as the length of a slice of `T`: `None` below zero, or where the slice's
/// bytes would exceed `isize::MAX`.
fn c_len<T>(count: impl core::convert::TryInto<isize>) -> Option<usize> {
    let len = usize::try_from(count.try_into().ok()?).ok()?;
    let bytes = len.checked_mul(core::mem::size_of::<T>())?;
    isize::try_from(bytes).is_ok().then_some(len)
}

/// A C `in` pointer and count as a slice: empty for null with a count of 0; `None` for null with
/// any other count, a misaligned pointer, or a count whose bytes exceed `isize::MAX`.
///
/// # Safety
///
/// A non-null `ptr` is valid for reads of `count` elements while the slice lives.
unsafe fn c_slice<'a, T>(
    ptr: *const T,
    count: impl core::convert::TryInto<isize>,
) -> Option<&'a [T]> {
    let len = c_len::<T>(count)?;
    if ptr.is_null() {
        return (len == 0).then_some(&[]);
    }
    if !ptr.is_aligned() {
        return None;
    }
    Some(unsafe { core::slice::from_raw_parts(ptr, len) })
}

/// A C `inout` buffer as the implementation's slice: `None` for a null or misaligned pointer, or a
/// count whose bytes exceed `isize::MAX`.
///
/// # Safety
///
/// A non-null `ptr` is valid for reads and writes of `count` initialised elements while the
/// slice lives.
unsafe fn c_slice_mut<'a, T>(
    ptr: *mut T,
    count: impl core::convert::TryInto<isize>,
) -> Option<&'a mut [T]> {
    let len = c_len::<T>(count)?;
    if ptr.is_null() || !ptr.is_aligned() {
        return None;
    }
    Some(unsafe { core::slice::from_raw_parts_mut(ptr, len) })
}

/// A C `out` buffer as the implementation's slice, zero-filled first, since the caller's memory
/// may be uninitialised: `None` for a null or misaligned pointer, or a count whose bytes exceed
/// `isize::MAX`.
///
/// # Safety
///
/// A non-null `ptr` is valid for writes of `count` elements while the slice lives, and `T` is
/// valid as all-zero bytes.
unsafe fn c_slice_zeroed<'a, T>(
    ptr: *mut T,
    count: impl core::convert::TryInto<isize>,
) -> Option<&'a mut [T]> {
    let len = c_len::<T>(count)?;
    if ptr.is_null() || !ptr.is_aligned() {
        return None;
    }
    unsafe { ptr.write_bytes(0, len) };
    Some(unsafe { core::slice::from_raw_parts_mut(ptr, len) })
}

/// every entry so far, those new since the last call, their labels' arena so far, and 1 on the final call
pub struct OnBatch<'a> {
    callback: unsafe extern "C" fn(
        seen: *const ffi::xy_entry,
        seen_count: u64,
        fresh: *const ffi::xy_entry,
        fresh_count: u64,
        arena: *const core::ffi::c_void,
        arena_count: u32,
        last: u32,
        user_data: *mut core::ffi::c_void,
    ) -> ffi::xy_flow,
    user_data: *mut core::ffi::c_void,
    _call: core::marker::PhantomData<&'a mut ()>,
}

impl OnBatch<'_> {
    /// Calls `xy_on_batch` with these views and values, which the implementation may do only during
    /// the call that passed it and on its thread; returns the callback's answer.
    pub fn call(
        &mut self,
        seen: &[Entry],
        fresh: &[Entry],
        arena: &[u8],
        last: u32,
    ) -> ffi::xy_flow {
        let seen_count =
            u64::try_from(seen.len()).expect("xy_on_batch: seen is longer than u64 can count");
        let fresh_count =
            u64::try_from(fresh.len()).expect("xy_on_batch: fresh is longer than u64 can count");
        let arena_count =
            u32::try_from(arena.len()).expect("xy_on_batch: arena is longer than u32 can count");
        // SAFETY: the caller passed this callback and its user_data for the call this wrapper is
        // borrowed for, and the wrapper is neither Send nor Sync; each view is a live slice and its length.
        unsafe {
            (self.callback)(
                seen.as_ptr(),
                seen_count,
                fresh.as_ptr(),
                fresh_count,
                arena.as_ptr().cast(),
                arena_count,
                last,
                self.user_data,
            )
        }
    }
}

/// a mode the library reports
pub struct OnMode<'a> {
    callback:
        unsafe extern "C" fn(mode: ffi::xy_mode, user_data: *mut core::ffi::c_void) -> ffi::xy_flow,
    user_data: *mut core::ffi::c_void,
    _call: core::marker::PhantomData<&'a mut ()>,
}

impl OnMode<'_> {
    /// Calls `xy_on_mode` with these views and values, which the implementation may do only during
    /// the call that passed it and on its thread; returns the callback's answer.
    pub fn call(&mut self, mode: ffi::xy_mode) -> ffi::xy_flow {
        // SAFETY: the caller passed this callback and its user_data for the call this wrapper is
        // borrowed for, and the wrapper is neither Send nor Sync; each view is a live slice and its length.
        unsafe { (self.callback)(mode, self.user_data) }
    }
}

/// every note so far and those new since the last call
pub struct OnNotes<'a> {
    callback: unsafe extern "C" fn(
        seen: *const ffi::xy_note_head,
        seen_count: u32,
        seen_bytes: u32,
        fresh: *const ffi::xy_note_head,
        fresh_count: u32,
        fresh_bytes: u32,
        user_data: *mut core::ffi::c_void,
    ) -> ffi::xy_flow,
    user_data: *mut core::ffi::c_void,
    _call: core::marker::PhantomData<&'a mut ()>,
}

impl OnNotes<'_> {
    /// Calls `xy_on_notes` with these views and values, which the implementation may do only during
    /// the call that passed it and on its thread; returns the callback's answer.
    pub fn call(&mut self, seen: NoteSequence<'_>, fresh: NoteSequence<'_>) -> ffi::xy_flow {
        let seen_count = seen.count();
        let seen_bytes = u32::try_from(seen.bytes().len())
            .expect("xy_on_notes: seen is longer than u32 can count");
        let fresh_count = fresh.count();
        let fresh_bytes = u32::try_from(fresh.bytes().len())
            .expect("xy_on_notes: fresh is longer than u32 can count");
        // SAFETY: the caller passed this callback and its user_data for the call this wrapper is
        // borrowed for, and the wrapper is neither Send nor Sync; each view is a live slice and its length.
        unsafe {
            (self.callback)(
                seen.bytes().as_ptr().cast(),
                seen_count,
                seen_bytes,
                fresh.bytes().as_ptr().cast(),
                fresh_count,
                fresh_bytes,
                self.user_data,
            )
        }
    }
}

